    $imgOut = "stitch_screens/images/$($item.name).png"
    $htmlOut = "stitch_screens/html/$($item.name).html"
    
    Write-Host "Downloading image for $($item.name)..."
    & curl.exe -s -L -o $imgOut $item.img
    
